macro_rules! deps {
    () => {
        Rng!();
        OsRng!();
    };
}

macro_rules! StdRng {
    () => {
        deps!();
        # [doc = " A strong, fast (amortized), non-portable RNG"] # [doc = ""] # [doc = " This is the \"standard\" RNG, a generator with the following properties:"] # [doc = ""] # [doc = " - Non-[portable]: any future library version may replace the algorithm"] # [doc = "   and results may be platform-dependent."] # [doc = "   (For a portable version, use the [rand_chacha] crate directly.)"] # [doc = " - [CSPRNG]: statistically good quality of randomness and [unpredictable]"] # [doc = " - Fast ([amortized](https://en.wikipedia.org/wiki/Amortized_analysis)):"] # [doc = "   the RNG is fast for bulk generation, but the cost of method calls is not"] # [doc = "   consistent due to usage of an output buffer."] # [doc = ""] # [doc = " The current algorithm used is the ChaCha block cipher with 12 rounds. Please"] # [doc = " see this relevant [rand issue] for the discussion. This may change as new"] # [doc = " evidence of cipher security and performance becomes available."] # [doc = ""] # [doc = " ## Seeding (construction)"] # [doc = ""] # [doc = " This generator implements the [`SeedableRng`] trait. Any method may be used,"] # [doc = " but note that `seed_from_u64` is not suitable for usage where security is"] # [doc = " important. Also note that, even with a fixed seed, output is not [portable]."] # [doc = ""] # [doc = " Using a fresh seed **direct from the OS** is the most secure option:"] # [doc = " ```"] # [doc = " # use rand::{SeedableRng, rngs::{StdRng, OsRng}};"] # [doc = " let rng = StdRng::try_from_rng(&mut OsRng).unwrap();"] # [doc = " # let _: StdRng = rng;"] # [doc = " ```"] # [doc = ""] # [doc = " Seeding via [`rand::rng()`](crate::rng()) may be faster:"] # [doc = " ```"] # [doc = " # use rand::{SeedableRng, rngs::StdRng};"] # [doc = " let rng = StdRng::from_rng(&mut rand::rng());"] # [doc = " # let _: StdRng = rng;"] # [doc = " ```"] # [doc = ""] # [doc = " Any [`SeedableRng`] method may be used, but note that `seed_from_u64` is not"] # [doc = " suitable where security is required. See also [Seeding RNGs] in the book."] # [doc = ""] # [doc = " ## Generation"] # [doc = ""] # [doc = " The generators implements [`RngCore`] and thus also [`Rng`][crate::Rng]."] # [doc = " See also the [Random Values] chapter in the book."] # [doc = ""] # [doc = " [portable]: https://rust-random.github.io/book/crate-reprod.html"] # [doc = " [Seeding RNGs]: https://rust-random.github.io/book/guide-seeding.html"] # [doc = " [unpredictable]: https://rust-random.github.io/book/guide-rngs.html#security"] # [doc = " [Random Values]: https://rust-random.github.io/book/guide-values.html"] # [doc = " [CSPRNG]: https://rust-random.github.io/book/guide-gen.html#cryptographically-secure-pseudo-random-number-generator"] # [doc = " [rand_chacha]: https://crates.io/crates/rand_chacha"] # [doc = " [rand issue]: https://github.com/rust-random/rand/issues/932"] # [derive (Debug , PartialEq , Eq)] pub struct StdRng (Rng) ;
    };
}

StdRng!()